class SeatManager {
    PriorityQueue<Integer> available=new PriorityQueue<>();
    public SeatManager(int n){
        for(int seat=1;seat<=n;seat++)available.offer(seat);
    }
    public int reserve(){
        return available.poll();
    }
    public void unreserve(int seatNumber){
        available.offer(seatNumber);
    }
}

code.kotlin:
class SeatManager(n:Int) {
    private val available=java.util.PriorityQueue<Int>();
    init{
        for(seat in 1..n)available.add(seat)
    };
    fun reserve():Int=available.remove();
    fun unreserve(seatNumber:Int){
        available.add(seatNumber)
    }
}

code.cpp:
class SeatManager {
    priority_queue<int,vector<int>,greater<int>> available;
    public:SeatManager(int n){
        for(int seat=1;seat<=n;++seat)available.push(seat);
    }
    int reserve(){
        int seat=available.top();
        available.pop();
        return seat;
    }
    void unreserve(int seatNumber){
        available.push(seatNumber);
    }
};
